#include<bits/stdc++.h>
using namespace std;
#define REP(i,st,ed) for(register int i=st,i##end=ed;i<=i##end;++i)
#define DREP(i,st,ed) for(register int i=st,i##end=ed;i>=i##end;--i)
typedef long long ll;
inline int read(){
	int x;
	char c;
	int f=1;
	while((c=getchar())!='-' && (c<'0' || c>'9'));
	if(c=='-') c=getchar(),f=-1;
	x=c^'0';
	while((c=getchar())>='0' && c<='9') x=(x<<1)+(x<<3)+(c^'0');
	return x*f;
}
inline ll readll(){
	ll x;
	char c;
	ll f=1;
	while((c=getchar())!='-' && (c<'0' || c>'9'));
	if(c=='-') c=getchar(),f=-1;
	x=c^'0';
	while((c=getchar())>='0' && c<='9') x=(x<<1ll)+(x<<3ll)+(c^'0');
	return x*f;
}
const int maxn=32,mod=1e9+7;
inline void add(int &x,int y){
	x+=y;
	if(x>=mod) x-=mod;
}
int n;
struct Matrix{
	int a[maxn][maxn];
	void clear(){
		memset(a,0,sizeof(a));
	}
	void output(){
		REP(i,1,n+1) REP(j,1,n+1) printf("%d%c",a[i][j],j==jend?'\n':' ');
		putchar('\n');
	}
	Matrix operator *(const Matrix &rhs) const{
		Matrix B;
		B.clear();
		REP(i,1,n+1) REP(j,1,n+1) REP(k,1,n+1) add(B.a[i][j],1ll*a[i][k]*rhs.a[k][j]%mod);
		return B;
	}
};
Matrix ans,E,A[maxn],pre[maxn],suf[maxn];
int main(){
#ifndef ONLINE_JUDGE
	freopen("matrix.in","r",stdin);
	freopen("matrix.out","w",stdout);
#endif
	ll m=readll();
	n=read();E.clear();
	REP(i,1,n+1) E.a[i][i]=1;
	ans=E;
	REP(i,1,n){
		A[i]=E;
		REP(j,1,n+1) A[i].a[j][i]=1;
	}
	pre[0]=suf[n+1]=E;
	for(;m;m/=n){
		ll u=m%n;
		if(u){
			ll s=0;
			for(ll v=m/n;v;v/=n) s=(s+v%n)%n;
			u=(s+u-1)%n+1;
			for(;u!=s;--u){
				if(u<=0) u+=n;
				ans=A[u]*ans;
			}
		}
		REP(i,1,n) pre[i]=pre[i-1]*A[i];
		DREP(i,n,1) suf[i]=A[i]*suf[i+1];
		REP(i,1,n) A[i]=suf[i]*pre[i-1];
	}
	int num=1;
	REP(i,1,n) add(num,ans.a[n+1][i]);
	printf("%d\n",num);
	return 0;
}

